#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/sys/mem_manage.h>
#include <zephyr/arch/x86/mmu.h> /* For K_MMU_PAGE_SIZE */

/*
 * This buffer simulates the memory region that the test_custom_cleanup_helper
 * thread attempts to access. The page fault occurred at address 0x70023.
 * We define a page-aligned buffer and simulate access at an offset within it.
 * The key is to ensure this memory region is properly mapped into the
 * thread's memory domain.
 */
#define CUSTOM_REGION_SIZE K_MMU_PAGE_SIZE
static char __aligned(K_MMU_PAGE_SIZE) custom_buffer[CUSTOM_REGION_SIZE];

/* Define a memory domain for the test. */
K_MEM_DOMAIN_DEFINE(test_mem_domain, 1, 1);

/*
 * The helper thread function that was identified in the error log as
 * 'test_custom_cleanup_helper'. This function attempts to access the
 * 'custom_buffer', which was previously unmapped or not properly mapped,
 * leading to a page fault.
 */
void test_custom_cleanup_helper(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    printk("test_custom_cleanup_helper: Attempting to access custom region...\n");

    /* Simulate the access that caused the page fault at 0x70023.
     * Our custom_buffer starts at a page boundary, so accessing offset 0x23
     * within it simulates the fault address within its page.
     */
    volatile char data = custom_buffer[0x23];

    printk("test_custom_cleanup_helper: Successfully accessed data: %d\n", data);

    /* Simulate some cleanup work that might have been intended by the test name. */
    printk("test_custom_cleanup_helper: Performing cleanup...\n");
}

K_THREAD_STACK_DEFINE(helper_stack, 1024);
struct k_thread helper_tid;

/*
 * The main test case function. It sets up the memory domain, maps the
 * custom memory region, creates and starts the helper thread, and then
 * performs cleanup.
 */
ZTEST_DMEM void test_custom_cleanup(void)
{
    printk("START - test_custom_cleanup\n");

    /* Initialize the memory domain. */
    k_mem_domain_init(&test_mem_domain);

    /* Define a memory partition for the 'custom_buffer'.
     * The permissions are set for supervisor (P) read/write and user (U) read/write.
     * Even for a supervisor thread, if a custom memory region is not explicitly
     * mapped into its memory domain, a 'PTE: not present' fault can occur.
     */
    struct k_mem_partition custom_partition = {
        .start = (uintptr_t)custom_buffer,
        .size = CUSTOM_REGION_SIZE,
        .attr = K_MEM_PARTITION_P_RW_U_RW
    };

    /*
     * This is the crucial fix: Add the defined memory partition to the
     * memory domain. This ensures that the MMU has a page table entry
     * for the 'custom_buffer' region, making it accessible.
     */
    int ret = k_mem_domain_add_partition(&test_mem_domain, &custom_partition);
    zassert_equal(ret, 0, "Failed to add custom partition to memory domain");

    /*
     * Create the helper thread. The error log indicates it's a supervisor thread.
     * We do not use K_USER flag here to ensure it remains a supervisor thread.
     */
    k_thread_create(&helper_tid, helper_stack, K_THREAD_STACK_SIZEOF(helper_stack),
                    test_custom_cleanup_helper, NULL, NULL, NULL,
                    K_PRIO_COOP(7), 0, K_FOREVER);

    /* Assign the thread to the memory domain. */
    k_thread_mem_domain_set(&helper_tid, &test_mem_domain);

    /* Start the thread and wait for it to complete. */
    k_thread_start(&helper_tid);
    k_thread_join(&helper_tid, K_FOREVER);

    /* Remove the partition from the domain during cleanup. This is good practice
     * for tests that manipulate memory domains.
     */
    ret = k_mem_domain_remove_partition(&test_mem_domain, &custom_partition);
    zassert_equal(ret, 0, "Failed to remove custom partition from memory domain");

    printk("END - test_custom_cleanup\n");
}

/* Define the test suite. */
ZTEST_SUITE(mem_protect_custom_cleanup, NULL, NULL, NULL, NULL, NULL);
